import{_ as a,o as r,c as o,ag as e}from"./chunks/framework.B3amng90.js";const s="/abu-aigc-guide/screenshots/drama-paste.webp",d="/abu-aigc-guide/examples/drama-storyboard.webp",m=JSON.parse('{"title":"从剧本制作短剧","description":"","frontmatter":{},"headers":[],"relativePath":"workflows/drama.md","filePath":"workflows/drama.md"}'),n={name:"workflows/drama.md"};function l(i,t,g,c,h,p){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="从剧本制作短剧" tabindex="-1">从剧本制作短剧 <a class="header-anchor" href="#从剧本制作短剧" aria-label="Permalink to &quot;从剧本制作短剧&quot;">​</a></h1><p>在侧栏打开 <strong>短剧</strong>。这节用《末班车》练习从一段原稿拆出三个镜头，先生成一小段确认风格，再继续制作整集。</p><h2 id="_1-导入原稿" tabindex="-1">1. 导入原稿 <a class="header-anchor" href="#_1-导入原稿" aria-label="Permalink to &quot;1. 导入原稿&quot;">​</a></h2><p>选择 <strong>粘贴正文</strong>，复制下方练习稿，再点击输入区右下角的 <strong>开始</strong>。如果已有文件，切换到 <strong>上传剧本 / 小说</strong>，支持 <code>txt</code>、<code>md</code>、<code>docx</code>。只有故事点子时，可以选 <strong>剧本创作</strong>。</p><blockquote><p>傍晚，雨刚停。林夏等在海边小城的电车站。远处传来铃声，她回头，看见最后一班电车从坡道驶来。暖黄色的车灯在湿润的轨道上拖出一道长长的倒影。</p></blockquote><p><a href="/abu-aigc-guide/screenshots/drama-paste.webp"><img src="'+s+'" alt="短剧的粘贴正文标签与开始按钮" loading="lazy"></a></p><h2 id="_2-确认剧本、角色和场景" tabindex="-1">2. 确认剧本、角色和场景 <a class="header-anchor" href="#_2-确认剧本、角色和场景" aria-label="Permalink to &quot;2. 确认剧本、角色和场景&quot;">​</a></h2><ol><li>创建项目时，画风可以选 <strong>90年代日式动画</strong>。进入项目后，先在 <strong>总览</strong> 检查主线和分集安排。</li><li>打开 <strong>剧本</strong>，用 <strong>生成分集剧本</strong> 或已有原稿准备第一集。调整好剧本后点击 <strong>资产拆解</strong>，选择第一集。</li><li>到 <strong>角色与场景</strong> 检查拆解结果。示例的角色是短发、穿米色衣服的林夏，场景是雨后海边小城的电车站。把人物外观和暖色车灯提前定下来，后续镜头可以复用。</li></ol><h2 id="_3-在片场检查分镜和模型" tabindex="-1">3. 在片场检查分镜和模型 <a class="header-anchor" href="#_3-在片场检查分镜和模型" aria-label="Permalink to &quot;3. 在片场检查分镜和模型&quot;">​</a></h2><p>在 <strong>片场</strong> 选第一集并生成分镜脚本。对照下图检查景别、角色动作和镜头顺序。表中的三镜各 4 秒，用于练习节奏，可按所选模型的时长范围调整。</p><p><a href="/abu-aigc-guide/examples/drama-storyboard.webp"><img src="'+d+'" alt="末班车分镜构图示意，依次为电车驶近、林夏回头、车灯和倒影" loading="lazy"></a></p><p><em>教程分镜示意，三种构图取自同一张内置画风预览图。</em></p><table tabindex="0"><thead><tr><th>时间</th><th>景别</th><th>可填入分镜的画面描述</th></tr></thead><tbody><tr><td>0–4 秒</td><td>远景</td><td>雨后的海边小城，夕阳映在湿润的轨道上，电车沿坡道慢慢驶近。</td></tr><tr><td>4–8 秒</td><td>近景</td><td>林夏听见铃声回头，短发与米色衣服保持一致，镜头轻轻推近。</td></tr><tr><td>8–12 秒</td><td>特写</td><td>聚焦暖黄车灯和轨道上的倒影，倒影随电车靠近慢慢拉长。</td></tr></tbody></table><h2 id="_4-试出一镜-再检查整集" tabindex="-1">4. 试出一镜，再检查整集 <a class="header-anchor" href="#_4-试出一镜-再检查整集" aria-label="Permalink to &quot;4. 试出一镜，再检查整集&quot;">​</a></h2><ol><li>在片场选中第二段，检查角色与场景引用，选择支持参考素材的视频模型。先确认当前片段的时长、比例和分辨率，再点 <strong>立即生成</strong>。</li><li>播放结果，检查回头动作、人物外观和光线。先改好这段，再生成其余片段，并为每段选定要采用的视频。</li><li>到 <strong>成片</strong> 页点击 <strong>合成整集</strong>，检查两处切换是否连续。满意后保存或下载。</li></ol>',15)])])}const b=a(n,[["render",l]]);export{m as __pageData,b as default};
